content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-09-weather-care-009

=== 用户原始指令 (query.txt) ===
弄个数字会跳的天气卡，点一下跳进应用，能念天气，不行了提醒

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "弄个数字会跳的天气卡，点一下跳进应用，能念天气，不行了提醒",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询地区名称，用于标识当前天气对象。",
            "sampleValue": "深圳"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本，作为动态跳变的主数字。",
            "sampleValue": "29°"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象，用于主值下方的短状态说明。",
            "sampleValue": "多云"
          },
          "alertLevel": {
            "type": "string",
            "description": "当前天气预警或异常提醒等级。",
            "sampleValue": "高温"
          }
        }
      }
    },
    "asset": {
      "primaryIcon": {
        "type": "string",
        "description": "当前天气状态图标资源路径。",
        "sampleValue": "resources/base/media/partly_cloudy.png"
      },
      "actionIcon": {
        "type": "string",
        "description": "打开天气应用或播报天气入口的图标资源路径。",
        "sampleValue": "resources/base/media/icon_weather1.png"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/partly_cloudy.png",
      "description": "彩色多云天气图标，适合用于天气卡片的状态识别。",
      "bindTo": "/asset/primaryIcon"
    },
    {
      "src": "resources/base/media/icon_weather1.png",
      "description": "天气/雨伞图标，适合用于天气关怀、天气应用入口或播报提示。",
      "bindTo": "/asset/actionIcon"
    }
  ]
}

